const defaults = { theme: "light" };

function readTheme(storage) {
  try {
    const raw = storage.getItem("app:theme");
    return raw === "dark" || raw === "light" ? raw : defaults.theme;
  } catch (error) {
    return defaults.theme;
  }
}

function saveTheme(storage, theme) {
  try {
    storage.setItem("app:theme", theme);
    return true;
  } catch (error) {
    return false;
  }
}

const key = "app:preferences";

try {
  localStorage.setItem(key, JSON.stringify({ theme: "dark" }));
} catch (error) {
  console.warn("Preference was not persisted", error);
}

window.addEventListener("storage", (event) => {
  if (event.key === key && event.newValue !== null) {
    console.log(JSON.parse(event.newValue).theme);
  }
});

const request = indexedDB.open("notes", 1);

request.onupgradeneeded = () => {
  const db = request.result;
  if (!db.objectStoreNames.contains("drafts")) {
    const store = db.createObjectStore("drafts", { keyPath: "id" });
    store.createIndex("by-updated", "updatedAt");
  }
};

request.onsuccess = () => {
  const db = request.result;
  db.onversionchange = () => db.close();
  console.log("database is ready");
};

request.onerror = () => console.error(request.error);

function saveDraft(db, draft) {
  const transaction = db.transaction("drafts", "readwrite");
  const store = transaction.objectStore("drafts");
  store.put(draft);

  transaction.oncomplete = () => console.log("committed");
  transaction.onabort = () => console.error(transaction.error);
  transaction.onerror = () => console.error("request or transaction failed");
}

function addDraft(db, draft) {
  const transaction = db.transaction("drafts", "readwrite");
  const store = transaction.objectStore("drafts");
  const request = store.add(draft); // insert only; duplicate keys can fail
  request.onsuccess = () => console.log("Request succeeded", request.result);
  request.onerror = () => console.error("Add request failed", request.error);
  transaction.oncomplete = () => console.log("Draft committed");
  transaction.onabort = () => console.error("Transaction aborted", transaction.error);
}

function readDraft(db, id) {
  const transaction = db.transaction("drafts", "readonly");
  const request = transaction.objectStore("drafts").get(id);
  request.onsuccess = () => console.log("Draft result", request.result);
  request.onerror = () => console.error("Read failed", request.error);
}

function saveDraft(db, draft) {
  const transaction = db.transaction("drafts", "readwrite");
  const request = transaction.objectStore("drafts").put(draft); // insert or replace
  request.onerror = () => console.error("Save request failed", request.error);
  transaction.oncomplete = () => console.log("Save transaction committed");
  transaction.onabort = () => console.error("Save transaction aborted", transaction.error);
}

function deleteDraft(db, id) {
  const transaction = db.transaction("drafts", "readwrite");
  const request = transaction.objectStore("drafts").delete(id);
  request.onerror = () => console.error("Delete failed", request.error);
  transaction.oncomplete = () => console.log("Delete transaction committed");
  transaction.onabort = () => console.error("Delete transaction aborted", transaction.error);
}

function listDraftsByDate(db, fromIso, toIso) {
  const transaction = db.transaction("drafts", "readonly");
  const index = transaction.objectStore("drafts").index("by-updated");
  const range = IDBKeyRange.bound(fromIso, toIso);
  const request = index.openCursor(range, "prev");
  request.onsuccess = () => {
    const cursor = request.result;
    if (!cursor) return; // no more matching records
    console.log(cursor.primaryKey, cursor.value);
    cursor.continue();
  };
  request.onerror = () => console.error("Cursor failed", request.error);
}

// getAll() is convenient when the complete result is small and needed at once.
